def has_close_elements(numbers: List[float], threshold: float) -> bool:
    for i in range(len(numbers)):
        for j in range(i + 1, len(numbers)):
            if abs(numbers[i] - numbers[j]) < threshold:
                return True
    return False

def below_zero(operations: List[int]) -> bool:
    balance = 0
    for op in operations:
        balance += op
        if balance < 0:
            return True
    return False

def mean_absolute_deviation(numbers: List[float]) -> float:
    if not numbers:
        return 0.0
    mean_val = sum(numbers) / len(numbers)
    return sum(abs(x - mean_val) for x in numbers) / len(numbers)

def max_product(num_str: str, N: int, K: int) -> int:
    # If more multiplications than possible cuts, return 0
    if K < 0 or K > N - 1:
        return 0

    # Precompute integer values of all substrings num_str[j:i] where 0 <= j < i <= N
    values = [[0] * N for _ in range(N)]
    for j in range(N):
        val = 0
        for i in range(j, N):
            val = val * 10 + (ord(num_str[i]) - 48)
            values[j][i] = val

def process_random_numbers(numbers: List[int]) -> Tuple[int, List[int]]:
    unique_numbers = sorted(set(numbers))
    return len(unique_numbers), unique_numbers

def polynomial_to_string(n: int, coeffs: list) -> str:
    """
    Convert polynomial coefficients into a formatted string.

    Parameters:
        n (int): Highest degree of the polynomial.
        coeffs (List[int]): Coefficients from highest degree to constant term.

    Returns:
        str: Polynomial string according to specified formatting rules.
    """
    terms = []
    first_term = True
    # Ensure coeffs length matches n+1
    if len(coeffs) != n + 1:
        raise ValueError("Length of coeffs must be n+1")
    for idx, coeff in enumerate(coeffs):
        if coeff == 0:
            continue
        degree = n - idx
        # Determine sign
        if first_term:
            sign = '-' if coeff < 0 else ''
            first_term = False
        else:
            sign = '-' if coeff < 0 else '+'
        abs_coeff = abs(coeff)
        # Determine coefficient string
        if abs_coeff == 1 and degree > 0:
            coeff_str = ''
        else:
            coeff_str = str(abs_coeff)
        # Determine variable part
        if degree == 0:
            var_part = ''
        elif degree == 1:
            var_part = 'x'
        else:
            var_part = f'x^{degree}'
        term = f"{sign}{coeff_str}{var_part}"
        terms.append(term)
    if not terms:
        return '0'
    return ''.join(terms)

def minimum_cost_to_merge_fruits(fruit_counts):
    # If there is zero or one heap, no cost is incurred.
    if not fruit_counts or len(fruit_counts) == 1:
        return 0

def min_groups(w, n, prices):
    prices.sort()
    left, right = 0, n - 1
    groups = 0
    while left <= right:
        if left == right:
            groups += 1
            break
        if prices[left] + prices[right] <= w:
            left += 1
            right -= 1
        else:
            right -= 1
        groups += 1
    return groups
